INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'f2c75331-21e8-5e2f-92f8-32e995be2411', '3398b479-241b-511d-9b72-3f69e368321e',
  'Xét hàm **func** được viết bằng ngôn ngữ C++ như sau.

Độ phức tạp về thời gian của hàm **func** theo kí hiệu Big-O là:

```cpp
int func(int n) {
    int a = 0;
    int i = n;
    while (i > 0) {
        a += i;
        i /= 2;
    }
    return a;
}
```

Lựa chọn:
- $O(\sqrt{n})$
- $O(n \log n)$
- $O(n)$
- $O(n^2 \log n)$
- $O(\log n)$', 8
);

