INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'be540466-d1d8-53af-a0ae-72566cadeb35', '3398b479-241b-511d-9b72-3f69e368321e',
  'Cho hàm `func` được viết bằng ngôn ngữ C++ như sau.

Với N = 32, số lần dòng lệnh `a = a + i + j;` được thực thi là

```cpp
int func(int N) {
    int a = 0;
    for(i = 0; i < N; i++) {
        for(j = N; j > i; j--) {
            a = a + i + j;
        }
    }
    return a;
}
```', 11
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'e1570817-8073-57d1-8cf0-4705b91a3e5e', '3398b479-241b-511d-9b72-3f69e368321e',
  'Xét hàm `func` được viết bằng ngôn ngữ C++.

Độ phức tạp về thời gian của hàm `func` theo ký hiệu Big-O là:

```cpp
int func(int n) {
    int sum = 0;
    for(int i = 1; i <= n; i *= 2) {
        for(int j = 1; j <= n; j++) {
            sum++;
        }
    }
    return sum;
}
```

Lựa chọn:
- $O(\sqrt{n})$
- $O(n \log n)$
- $O(n)$
- $O(n^2 \log n)$
- $O(\log n)$', 12
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '8410e370-888e-5a7c-9516-831d5604ddf9', '3398b479-241b-511d-9b72-3f69e368321e',
  'Xét hàm `func` được viết bằng ngôn ngữ C++ như sau.

Độ phức tạp về thời gian của hàm `func` theo kí hiệu Big-O là:

```cpp
void func(int n) {
    int i, j;
    for (i = 0 ; i <= n; ++i) {
        for (j = 0 ; j < n; j+=i) {
            std::cout << i << " " << j;
        }
    }
}
```

Lựa chọn:
- $O(n\sqrt{n})$
- $O(n \log n)$
- $O(n)$
- $O(n^2 \log n)$
- $O(\log n)$', 13
);

